record Order(String shopId, BigDecimal total, BigDecimal discount, BigDecimal toPay) {}
record Budget(List<Entry> entries) {
    Budget { entries = List.copyOf(entries); }               // snapshot: nobody can change it later
    Budget posting(List<Entry> more) {                       // a new version, by copying everything
        List<Entry> all = new ArrayList<>(entries);
        all.addAll(more);
        return new Budget(all);
    }
}

static BigDecimal discount(BigDecimal total, BigDecimal rate) {   // pure: same inputs, same output
    return total.multiply(rate).setScale(2, RoundingMode.HALF_EVEN);
}

