static String originOf(String id, Map<String, Starter> byId) {
    String current = id;
    while (true) {
        String parent = byId.get(current).parentId();
        if (parent == null) return current;   // no parent: this is the first starter
        current = parent;                     // what tailrec's goto does
    }
}
